    async def add_colormap(self, name: Any, cmap: Any) -> Any:
        """Register a colormap by name so it becomes available to `setVolume({ colormap: name })`, `nv1.colormaps`, colorbars, mesh layers, and so on.

        Use this to add user-defined LUTs at runtime.
        Re-registering an existing name replaces the entry. Does not trigger a
        redraw — the colormap is inert until a volume references it. Volumes
        that already use the name show the new colors on their next GPU update
        (e.g. `updateGLVolume()`). Mesh layers, tracts and connectomes bake their
        colors when built, so they pick them up on their next change
        (`setMeshLayerProperty`, `setTractOptions`, `setConnectomeOptions`, ...).

        A `labels` array (empty is fine) registers a label table: volumes using
        it look up colours by integer ID with nearest sampling and no display
        window, and `I` defaults to 0..n-1. Re-registering a name rebuilds the
        label LUT of every volume using it in this viewer; `updateGLVolume()`
        shows it. Other viewers keep the old colours until their volume is
        given the colormap again (`setVolume`).

        Parameters
        ----------
        name : string
        cmap : Pick<ColorMap, \"R\" | \"G\" | \"B\"> & Partial<Pick<ColorMap, \"A\" | \"I\" | \"labels\">>

        Returns
        -------
        string
            The canonical name under which the colormap was stored
            (first letter upper-cased), which is the form visible in `nv1.colormaps`
            and the `colormapAdded` event detail.
        """
        return await self._request("addColormap", _make_args(name, cmap))

    def add_colormap_from_url(self, url: Any, name: Any = _UNSET) -> None:
        """Fetch a colormap JSON (`{ R, G, B, A?, I?, labels? }`) from a URL or `File` and register it under `name`.

        When `name` is omitted, it is derived from
        the source filename; callers passing an un-nameable source (e.g.
        `?query-only`) should supply `name` explicitly — an empty derived
        name throws.

        Parameters
        ----------
        url : string | File
        name : string | undefined
        """
        self.send({"cmd": "addColormapFromUrl", "args": _make_args(url, name)})

